": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-session-format-catalog\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session-format-v0-to-v1\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session-format-v1-to-v2\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session-format-v2-to-v3\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session-format-v3-to-v4\": \"0.1.7-rc.2\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  }\n}\n"
