      "path": "cordis.patch.yml",
      "content": "# dsh bundle patch: inserts dsh-codex-sync into a profile's layer stack.\n#\n# Add this package to a profile's `dsh.profile.bundles` (or `dsh plugin add`)\n# and this layer auto-mounts the plugin with the defaults below. Every option\n# can be overridden by a later row or the profile's own cordis.patch.yml\n# (later layers win in this harness).\n#\n#   dsh --profile <name> plugin add dsh-codex-sync   (or list it in bundles)\n#   then restart dsh web.\n#\n# Config reference (all optional):\n#   codexHome:            codex config dir            (default ~/.codex)\n#   maxSkills:            max codex skills registered (default 100)\n#   enableSkills:         register first-class skills (default true)\n#   enableInstructions:   inject instructions.md      (default true)\n#   enableConfig:         inject config.toml summary  (default true)\n#   enableImport:         /import-codex & friends     (default true)\n#   maxSessionBytes:      import skip size guard      (default 256 MiB)\n#   mcpServers:           explicit MCP servers to mount\n#   mcpMirror:            auto-mirror codex mcp servers (default true)\n#   mcpMirrorDeny:        extra names never mirrored\n#   mcpMirrorOnly:        mirror ONLY these names\n- insert:\n    - id: codex-sync\n      name: 'dsh-codex-sync'\n      config: {}\n"
